/* Optional elevator teaching is a live read of the existing interlock controller.
 * No browser/dependency needed. Run: node qa/audit-elevator-interlock-lesson.cjs
 * Source/final-state parity is anchored to the parent-specified frozen baseline. */
'use strict';
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict'),cp=require('./portable-baseline.cjs'),crypto=require('node:crypto');
const root=path.resolve(__dirname,'..'),baselineRef='898db54';
const read=p=>fs.readFileSync(path.join(root,p),'utf8'),source=read('dist/scenes/elevator.js');
const baseline=cp.execFileSync('git',['show',baselineRef+':dist/scenes/elevator.js'],{cwd:root,encoding:'utf8'});
const clone=value=>JSON.parse(JSON.stringify(value));
const hash=value=>crypto.createHash('sha256').update(value).digest('hex');
const results=[];let frames=0,parityFrames=0;
function test(name,fn){try{fn();results.push({name,ok:true});}catch(e){results.push({name,ok:false,error:e.stack});}}
function make(code=source){let mounted=null,invalidations=0;const ctx={window:{MuseumObservation:{mountLesson(options){mounted=options;return{};}}},console,addEventListener(){},URLSearchParams,performance:{now:()=>0}};vm.createContext(ctx);vm.runInContext(read('dist/core.js'),ctx);vm.runInContext(code,ctx);const cfg=ctx.window.SCENES.elevator(),steps=new Set(),messages=[];
 const ui={animate(fn){steps.add(fn);},invalidate(){invalidations++;},flash(text){messages.push(text);}},state=cfg.state;
 cfg.setup?.(ui);
 const frame=(dt=1/60)=>{for(const f of [...steps])if(f(dt)===false)steps.delete(f);};
 const tick=(seconds,dt=1/60)=>{for(let t=0;t<seconds-1e-8;t+=dt)frame(Math.min(dt,seconds-t));};
 const click=label=>{const b=cfg.buttons.find(b=>b.label===label);assert(b,'Missing '+label);b.onClick(state,ui);};
 const toggle=on=>cfg.lesson.onToggle(state,on,ui),choice=id=>cfg.lesson.onChoice(state,id,ui),snap=()=>cfg.lesson.read(state);
 return{cfg,state,ui,steps,messages,frame,tick,click,toggle,choice,snap,get mounted(){return mounted;},get invalidations(){return invalidations;}};
}
function check(t){const s=t.state,before=JSON.stringify(s),snap=t.snap();assert.equal(JSON.stringify(s),before,'Reading teaching changed controller state');assert.equal(snap.paused,false);assert.equal(snap.completed,false,'Live phases must not become a completed linear lesson');assert.equal(snap.phase,s.phase);assert.equal(snap.position,s.pos);assert.equal(snap.door,s.door);assert.deepEqual(clone(snap.queue),clone(s.queue));assert.equal(snap.choices.length,5);assert(snap.title&&snap.text&&snap.look&&snap.label);assert(!/null|undefined|NaN|Infinity/.test(snap.text));
 const aligned=s.phase!=='moving'&&Math.abs(s.pos-Math.round(s.pos/33)*33)<1e-6?Math.round(s.pos/33)+1:null;
 assert.equal(snap.alignedFloor,aligned);
 for(let i=0;i<3;i++){assert.equal(snap.landingDoors[i],aligned===i+1?s.door:0);assert.equal(snap.landingLocks[i],aligned!==i+1||s.door===0&&s.phase!=='opening');}
 if(s.phase==='moving'){assert.equal(s.door,0);assert.equal(snap.allLocked,true);assert.equal(snap.index,1);assert.equal(snap.alignedFloor,null);}
 else{assert.equal(s.pos,(s.floor-1)*33,'Stationary controller not level');assert.equal(snap.alignedFloor,s.floor);}
 assert(s.pos>=0&&s.pos<=66&&s.door>=0&&s.door<=1);assert.equal(new Set(s.queue).size,s.queue.length);assert(t.steps.size<=2);frames++;return snap;
}
test('Geometry, alignment/lock helpers and occlusion source remain byte-identical; controller timing has a separate regression',()=>{
 const segments=[['geometry and cache',s=>s.slice(s.indexOf(' const access='),s.indexOf(' const observation='))],['lock helpers',s=>s.slice(s.indexOf(' const alignedFloor='),s.indexOf(' function describe('))]];
 for(const [name,part]of segments)assert.equal(hash(part(source)),hash(part(baseline)),name+' changed');
 const oldOcclusion=cp.execFileSync('git',['show',baselineRef+':dist/elevator-occlusion.js'],{cwd:root,encoding:'utf8'});assert.equal(hash(read('dist/elevator-occlusion.js')),hash(oldOcclusion));
});
test('Default is free play; mounting, opening and closing the lesson create no animation or state edits',()=>{const t=make(),before=clone(t.state);assert.equal(t.snap().enabled,false);assert.equal(t.mounted.id,'elevator');assert.equal(t.mounted.linear,false);assert.equal(t.cfg.lesson.linear,false);assert.equal(t.mounted.exitLabel,'退出讲解 · 继续自由操作');assert.deepEqual(clone(t.mounted.route),['关','行','平','开']);t.cfg.acts.lessonAdvance(t.state,{},t.ui);t.cfg.acts.lessonChoice(t.state,{dataset:{choice:'floor-3'}},t.ui);assert.deepEqual(clone(t.state),before);t.mounted.onToggle(true);assert.equal(t.snap().enabled,true);assert.deepEqual(clone(t.state),before);assert.equal(t.steps.size,0);t.mounted.onToggle(false);assert.equal(t.snap().enabled,false);assert.deepEqual(clone(t.state),before);check(t);});
test('Primary action calls a real floor;关→行→平→开 follow actual frames without inserting a pause',()=>{const t=make(),seen=new Set();t.toggle(true);t.mounted.onAdvance();for(let i=0;i<500;i++){t.frame();const s=check(t);seen.add(s.index);if(t.state.phase==='opening'&&t.state.door===0){assert.equal(s.index,2);const pos=t.state.pos;t.frame();assert(t.state.door>0);assert.equal(t.state.pos,pos);assert.equal(t.snap().index,3);}}assert.deepEqual([...seen].sort(),[0,1,2,3]);assert.equal(t.state.floor,2);assert.equal(t.state.trips,1);assert.equal(t.steps.size,0);});
test('Manual close holds cabin level and the closed-door snapshot does not imply automatic travel',()=>{const t=make();t.toggle(true);t.choice('close');for(let i=0;i<70;i++){t.frame();const s=check(t);if(t.state.phase==='manualClose')assert.equal(s.index,0);}assert.equal(t.state.phase,'idle');assert.equal(t.state.pos,0);assert.equal(t.state.door,0);assert.equal(t.snap().index,2);assert(t.snap().text.includes('还要有楼层呼叫'));t.choice('floor-3');t.frame();const s=check(t);assert.equal(t.state.phase,'moving');assert.equal(t.state.door,0);assert(s.text.includes('都已关闭锁住'));});
test('Reopen reverses real door motion continuously and preserves the queued destination',()=>{const t=make();t.toggle(true);t.choice('floor-3');t.tick(.35);const opening=t.state.door;assert.equal(t.state.phase,'closing');assert.equal(t.snap().choices.find(c=>c.id==='open').disabled,false);t.choice('open');assert.equal(t.state.door,opening);assert.equal(t.state.phase,'opening');assert.deepEqual(clone(t.state.queue),[3]);assert.equal(t.snap().completed,false);t.tick(.1);assert(t.state.door>opening);t.tick(15);assert.equal(t.state.floor,3);assert.equal(t.state.trips,1);assert.equal(t.steps.size,0);check(t);});
test('Calling the current floor while closing remains a direct reopen, not a disabled duplicate',()=>{const t=make();t.toggle(true);t.choice('floor-2');t.tick(.35);const c=t.snap().choices.find(c=>c.id==='floor-1');assert.equal(c.disabled,false);assert(c.label.includes('重新开门'));const d=t.state.door;t.choice('floor-1');assert.equal(t.state.phase,'opening');assert.equal(t.state.door,d);assert.deepEqual(clone(t.state.queue),[2]);check(t);});
test('Moving open request demonstrates controller refusal without unlocking, pausing or cancelling queue',()=>{const t=make();t.toggle(true);t.choice('floor-3');t.tick(1.4);assert.equal(t.state.phase,'moving');const before=clone(t.state),c=t.snap().choices.find(c=>c.id==='open');assert.equal(c.disabled,false);assert(c.hint.includes('拒绝'));t.choice('open');assert.deepEqual(clone(t.state),before);assert(t.messages.at(-1).includes('不能开门'));t.choice('floor-2');t.choice('floor-2');assert.deepEqual(clone(t.state.queue),[2]);assert.equal(t.snap().choices.find(c=>c.id==='floor-2').disabled,true);const pos=t.state.pos;t.frame();assert(t.state.pos>pos);check(t);t.tick(20);assert.equal(t.state.floor,2);assert.equal(t.state.trips,2);assert.equal(t.steps.size,0);});
test('Closing during opening reverses continuously; completed stays false with queued onward service',()=>{const t=make();t.toggle(true);t.choice('floor-3');t.choice('floor-2');while(t.state.phase!=='opening')t.frame();t.tick(.3);const d=t.state.door;assert.equal(t.snap().choices.find(c=>c.id==='close').disabled,false);t.choice('close');assert.equal(t.state.door,d);assert.equal(t.state.phase,'manualClose');assert.deepEqual(clone(t.state.queue),[2]);t.frame();assert(t.state.door<d);assert.equal(t.snap().completed,false);t.tick(20);assert.equal(t.state.floor,2);assert.equal(t.steps.size,0);check(t);});
test('Extending dwell uses the original timer and does not mark the queue as finished',()=>{const t=make();t.toggle(true);t.choice('floor-2');t.choice('floor-3');while(t.state.phase!=='waiting')t.frame();t.tick(.6);assert(t.state.timer>0);t.choice('open');assert.equal(t.state.timer,0);assert.deepEqual(clone(t.state.queue),[3]);assert.equal(t.snap().completed,false);assert(t.snap().text.includes('待响应：3楼'));t.tick(15);assert.equal(t.state.floor,3);assert.equal(t.state.trips,2);check(t);});
test('Reset invalidates callbacks during every real phase and does not leave a teaching pause',()=>{for(const phase of ['closing','manualClose','moving','opening','waiting']){const t=make();t.toggle(true);t.choice(phase==='manualClose'?'close':'floor-3');for(let i=0;i<1000&&t.state.phase!==phase;i++)t.frame();assert.equal(t.state.phase,phase);t.click('回到一楼');t.tick(10);assert.equal(t.state.floor,1);assert.equal(t.state.trips,0);assert.equal(t.state.door,1);assert.equal(t.state.phase,'idle');assert.equal(t.steps.size,0);assert.equal(t.snap().enabled,true);check(t);}});
test('Existing observer reads the same phase and lock truth, including closed stationary doors',()=>{const t=make();t.toggle(true);for(const id of ['close','floor-3','open','floor-2']){t.choice(id);for(let i=0;i<240;i++){t.frame();const s=check(t),o=t.cfg.observation.read(t.state);assert.equal(o.stage,s.title);assert.equal(o.text,s.text);const lock=o.readouts.find(r=>r.label==='厅门锁').value;assert.equal(lock,s.allLocked?'全部锁闭':s.alignedFloor+'楼释放 · 其余锁闭');}}});
test('Current free play and teaching controls have frame-exact equal motion through 360 mixed commands',()=>{const t=make(),old=make(source),ids=['floor-1','floor-2','floor-3','open','close'],labels=['前往一楼','前往二楼','前往三楼','开门','关门'];let seed=731;for(let k=0;k<360;k++){seed=seed*16807%2147483647;const index=seed%5;t.toggle(true);t.choice(ids[index]);old.click(labels[index]);if(k%13===0){t.toggle(false);t.toggle(true);}if(k%47===0){t.click('回到一楼');old.click('回到一楼');}for(let i=0;i<seed%30+1;i++){t.frame();old.frame();assert.deepEqual(clone(t.state),clone(old.state));assert.equal(t.steps.size,old.steps.size);check(t);parityFrames++;}}for(let i=0;i<3600;i++){t.frame();old.frame();assert.deepEqual(clone(t.state),clone(old.state));check(t);parityFrames++;}assert.equal(t.steps.size,0);assert.equal(old.steps.size,0);});
function integrated(){
 const f=require('./review-process-invariants.cjs').fixture('elevator'),d=f.document,proto=Object.getPrototypeOf(d);
 proto.focus=function(){d.activeElement=this;};proto.scrollIntoView=function(){};proto.contains=function(n){return n===this||this.children.some(c=>c.contains(n));};
 const dock=d.createElement('section'),primary=d.createElement('div'),extras=d.createElement('div');dock.className='play-dock';primary.id='btns';primary.className='actions';extras.className='dock-extras';dock.append(primary,extras);d.body.append(dock);
 f.mount();const panel=f.ui.observation.panel,host=panel.parentElement;host.remove();extras.append(host);const guide=panel.querySelector('.elevator-guide');
 return{f,d,dock,primary,extras,panel,guide,read:()=>f.cfg.lesson.read(f.s),open(){f.toggle(panel,true);f.toggle(guide,true);},choice(id){const b=guide.querySelector('[data-choice="'+id+'"]');assert(b,'UI choice '+id);b.click();return b;}};
}
test('Shared helper integration: optional closed guide folds/restores original controls without state changes',()=>{const t=integrated(),{f,guide,panel,primary,dock}=t,before=f.snapshot();assert.equal(panel.open,false);assert.equal(guide.open,false);assert.equal(t.read().enabled,false);t.open();assert.equal(t.read().enabled,true);assert.equal(guide.parentElement,dock);assert.equal(primary.parentElement.className,'lesson-free-controls elevator-free-controls');assert.equal(primary.parentElement.open,false);assert.equal(f.snapshot(),before);assert.equal(guide.querySelector('.mechanism-lesson-hold').hidden,true);assert(guide.querySelector('.mechanism-lesson-title').textContent.startsWith('当前 · '));for(const dot of guide.querySelectorAll('.mechanism-lesson-route span'))assert.equal(dot.dataset.done,'false');assert.equal(guide.querySelectorAll('[aria-current="step"]').length,1);guide.querySelector('.mechanism-lesson-exit').click();assert.equal(primary.parentElement,dock);assert.equal(t.read().enabled,false);assert.equal(f.snapshot(),before);assert.equal(dock.querySelectorAll('#btns').length,1);f.finish();assert.equal(f.pending,0);});
test('Shared helper integration: live choices reject moving open, retain FIFO, and exit never pauses travel',()=>{const t=integrated(),{f,guide}=t;t.open();t.choice('floor-3');f.tick(1.4);assert.equal(f.s.phase,'moving');assert(guide.querySelector('.mechanism-lesson-title').textContent.includes('行 · '));assert.equal(guide.querySelector('.mechanism-lesson-go').getAttribute('aria-disabled'),'true');const at=f.snapshot();t.choice('open');assert.equal(f.snapshot(),at);assert(f.flashes.at(-1).includes('不能开门'));t.choice('floor-2');assert.deepEqual(clone(f.s.queue),[2]);assert.equal(guide.querySelector('[data-choice="floor-2"]').disabled,true);for(const dot of guide.querySelectorAll('.mechanism-lesson-route span'))assert.equal(dot.dataset.done,'false');const pos=f.s.pos;guide.querySelector('.mechanism-lesson-exit').click();f.frame();assert(f.s.pos>pos);assert.equal(t.read().enabled,false);f.finish();assert.equal(f.s.floor,2);assert.equal(f.s.trips,2);assert.equal(f.pending,0);});
test('Shared helper integration: observer close/reopen and hidden-page resume retain the same controller',()=>{const t=integrated(),{f,panel,guide}=t;t.open();t.choice('floor-3');f.tick(1.4);const before=f.snapshot();f.document.hidden=true;f.document.emit('visibilitychange');f.tick(10);assert.equal(f.snapshot(),before);assert.equal(f.pending,0);f.document.hidden=false;f.document.emit('visibilitychange');f.frame();assert(f.s.pos>JSON.parse(before).pos);f.toggle(panel,false);assert.equal(guide.open,false);assert.equal(t.read().enabled,false);assert.equal(t.primary.parentElement,t.dock);const pos=f.s.pos;f.frame();assert(f.s.pos>pos);t.open();assert.equal(t.read().enabled,true);assert.equal(t.read().index,1);f.finish();assert.equal(f.s.floor,3);assert.equal(f.s.trips,1);assert.equal(f.pending,0);});
const report={baselineRef,scope:'elevator setup, live interlock explanation, observer and QA only',browser:false,dom:'Production observation helper and RAF with DOM doubles; not a browser layout test',frames,parityFrames,results};
console.log(JSON.stringify(report,null,2));fs.writeFileSync(path.join(__dirname,'elevator-interlock-lesson-results.json'),JSON.stringify(report,null,2)+'\n');if(results.some(r=>!r.ok))process.exitCode=1;
